//! 10-18 (CLI-03..08): `ostro completions <shell>` on the real binary.
//!
//! The scripts are generated by clap_complete from the live clap tree, so they change
//! whenever a verb or flag is added. No full-script snapshot (W3a): each script is only
//! checked to contain the Phase 10 verbs and flags. Phase 11 verbs are checked by
//! `cli_p11.rs`; any other verb is ignored here.

#[path = "common/p10.rs"]
mod p10;

const SHELLS: [&str; 5] = ["bash", "zsh", "fish", "powershell", "elvish"];

const VERBS: [&str; 7] = [
    "init",
    "build",
    "deploy",
    "replay",
    "toolchain",
    "doctor",
    "completions",
];

/// Long flags without the leading `--`: `dev --time-skipping/--watch`,
/// `replay --module/--sample/--corpus`.
const FLAGS: [&str; 5] = ["time-skipping", "watch", "module", "sample", "corpus"];

fn completions(shell: &str) -> String {
    let cwd = tempfile::tempdir().expect("tempdir");
    let (code, out, err) = p10::run_cli_in(cwd.path(), &["completions", shell], &[]);
    assert_eq!(code, 0, "completions {shell}: {err}");
    assert!(err.is_empty(), "completions {shell} wrote to stderr: {err}");
    assert!(!out.trim().is_empty(), "completions {shell}: empty script");
    out
}

/// `word` occurs in `s` delimited by characters that cannot be part of a verb or flag
/// name (so `build` does not match inside `build-info`).
fn has_word(s: &str, word: &str) -> bool {
    let part = |c: char| c.is_ascii_alphanumeric() || c == '-' || c == '_';
    s.match_indices(word).any(|(i, _)| {
        let before = s[..i].chars().next_back().is_none_or(|c| !part(c));
        let after = s[i + word.len()..].chars().next().is_none_or(|c| !part(c));
        before && after
    })
}

/// A long flag in a script: `--name` everywhere, `-l name` in fish.
fn has_flag(shell: &str, s: &str, name: &str) -> bool {
    if shell == "fish" {
        s.contains(&format!("-l {name}"))
    } else {
        has_word(s, &format!("--{name}"))
    }
}

#[test]
fn every_shell_lists_phase10_verbs_and_flags() {
    for shell in SHELLS {
        let script = completions(shell);
        for verb in VERBS {
            assert!(
                has_word(&script, verb),
                "{shell} completions lack the verb {verb}"
            );
        }
        for flag in FLAGS {
            assert!(
                has_flag(shell, &script, flag),
                "{shell} completions lack the flag --{flag}"
            );
        }
    }
}

#[test]
fn unknown_shell_exits_2() {
    let cwd = tempfile::tempdir().expect("tempdir");
    let (code, out, err) = p10::run_cli_in(cwd.path(), &["completions", "tcsh"], &[]);
    assert_eq!(code, 2, "{out}{err}");
    assert!(out.is_empty(), "{out}");
    assert!(err.contains("tcsh"), "{err}");
    let (code, _, err) = p10::run_cli_in(cwd.path(), &["completions"], &[]);
    assert_eq!(code, 2, "{err}");
}

#[test]
fn help_documents_install_lines() {
    let cwd = tempfile::tempdir().expect("tempdir");
    let (code, out, err) = p10::run_cli_in(cwd.path(), &["completions", "--help"], &[]);
    assert_eq!(code, 0, "{err}");
    assert!(
        out.contains("ostro completions zsh > ~/.zfunc/_ostro"),
        "{out}"
    );
    for shell in SHELLS {
        assert!(out.contains(shell), "{shell} missing from --help:\n{out}");
    }
}

#[test]
fn bash_script_parses() {
    let has_bash = std::process::Command::new("bash")
        .arg("--version")
        .output()
        .is_ok_and(|o| o.status.success());
    if !has_bash {
        eprintln!("bash not found; skipping the syntax check");
        return;
    }
    let dir = tempfile::tempdir().expect("tempdir");
    let path = dir.path().join("ostro.bash");
    std::fs::write(&path, completions("bash")).expect("write script");
    let out = std::process::Command::new("bash")
        .arg("-n")
        .arg(&path)
        .output()
        .expect("bash -n");
    assert!(
        out.status.success(),
        "bash -n: {}",
        String::from_utf8_lossy(&out.stderr)
    );
}
